{[x;y]
    apply: {[op; left; right]
        if[op = "*"; :left * right];
        if[op = "//"; :left div right];
        if[op = "**"; :left xexp right];
        if[op = "+"; :left + right];
        :left - right
    };
    processHighPrec: {[ops; operands; applyFunc]
        idx: where ops in ("*"; "//"; "**");
        if[0 = count idx; :(ops; operands)];
        i: first idx;
        val: applyFunc[ops[i]; operands[i]; operands[i+1]];
        newOps: (i#ops) , (i+1_ops);
        newOperands: (i#operands) , (enlist val) , ((i+2)_operands);
        .z.s[newOps; newOperands; applyFunc]
    };
    processLowPrec: {[ops; operands; applyFunc]
        if[0 = count ops; :operands[0]];
        val: applyFunc[ops[0]; operands[0]; operands[1]];
        newOps: ops[1:];
        newOperands: (enlist val) , (operands[2:]);
        .z.s[newOps; newOperands; applyFunc]
    };
    result: processHighPrec[x; y; apply];
    processLowPrec[result[0]; result[1]; apply]
    }

